using Lastlight.Core;
using System.Text.Json;
public static class InstitutionAcceptance
{
 public static void Run(Definitions d,string output,string assets)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Cmd(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,c.Text+": "+r.Message);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Save(string name,World w,string tab="Assign"){SaveStore.Write(Path.Combine(output,name+".lastlight"),w,new(){CameraX=64,CameraY=64,OpenTab=tab},d);}void Until(World w,Func<bool> done,int limit,string label){for(int i=0;i<limit&&!done();i++)w.Step(d);Require(done(),label+" stalled: "+string.Join("/",w.Colony.People.Values.Select(p=>p.Activity)));w.Validate(d);}
  var w=InstitutionsWorldGenerator.Create(d,74219);Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(InstitutionsWorldGenerator.Create(d,74219)),"H world not reproducible.");long teacher=w.Colony.People.Keys.First(),student=w.Colony.People.Keys.Skip(1).First();w.Colony.People[teacher].Skills[15]=18;w.Colony.People[student].Skills[15]=1;
  var host=w.Entities.First(e=>e.DefinitionId=="study");Cmd(w,new(CommandKind.InstitutionAction,teacher,"Library",TargetId:host.Id,Text:"found"));var school=w.Society.Institutions.Single();Cmd(w,new(CommandKind.InstitutionAction,student,TargetId:school.Id,Text:"join"));Cmd(w,new(CommandKind.InstitutionAction,teacher,TargetId:student,Quantity:(int)school.Id,Text:"apprentice"));Cmd(w,new(CommandKind.InstitutionAction,teacher,"Partners",TargetId:student,Text:"family"));Require(!w.Apply(new(CommandKind.InstitutionAction,student,"Partners",TargetId:teacher,Text:"family"),d).Accepted,"Duplicate family accepted.");
  foreach(long id in new[]{teacher,student}){w.Interrupt(id,d);w.Colony.People[id].Schedule=Enumerable.Repeat(ScheduleActivity.Study,24).ToArray();w.Colony.People[id].Food=1000;w.Colony.People[id].Rest=1000;}
  Until(w,()=>w.Society.Apprentices.Single().Graduated,20000,"Autonomous attending apprenticeship");Require(w.Colony.People[student].Skills[15]>1&&school.Sessions>=8&&w.Region.History.Any(h=>h.Kind=="Graduation"),"Training or graduation not persisted.");Save("institutions-and-family",w);var restored=SaveStore.Read(Path.Combine(output,"institutions-and-family.lastlight"),d).World;Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(restored),"H roundtrip differs.");Steps(w,300);Steps(restored,300);Require(SaveStore.Fingerprint(w)==SaveStore.Fingerprint(restored),"H continuation diverged.");Console.WriteLine("PASS H01–H03: actual building membership, Study pathing, attending keeper/mentor, permanent apprenticeship learning, graduation, exclusive adult family bonds and deterministic reload");
  Cmd(w,new(CommandKind.InstitutionAction,DefinitionId:"Mutual care",Text:"covenant"));var bed=w.Entities.First(e=>e.DefinitionId=="bed");Cmd(w,new(CommandKind.MedicalBed,bed.Id,Quantity:1));w.Tick=(w.Tick/World.TicksPerDay+1)*World.TicksPerDay-1;Steps(w,1);Require(w.Colony.People[teacher].Priorities[2]==1&&w.Danger.People[teacher].Memories.Any(m=>m.Kind=="Covenant"&&m.Value>0),"Covenant practice has no behavior/mood effect.");
  var chamber=InstitutionsWorldGenerator.Create(d,74219);long keeper=chamber.Colony.People.Keys.First();foreach(var id in chamber.Colony.People.Keys)chamber.Colony.People[id].Schedule=Enumerable.Repeat(ScheduleActivity.Sleep,24).ToArray();var spawn=chamber.Apply(new(CommandKind.Spawn,DefinitionId:"vault-guardian",X:62,Y:67),d);Require(spawn.Accepted,spawn.Message);var guardian=chamber.Find(spawn.EntityId)!;chamber.Body(guardian.Id)!.Downed=true;Cmd(chamber,new(CommandKind.Teleport,keeper,X:61,Y:67));Cmd(chamber,new(CommandKind.InstitutionAction,keeper,TargetId:guardian.Id,Text:"contain"));var q=chamber.Society.Containments.Single();Require(chamber.IsContained(guardian.Id)&&!chamber.CanAct(guardian.Id)&&chamber.ContainmentRequirements(q).Any(r=>!r.Value),"Containment ignores custody/requirements.");Save("containment-warning",chamber);Steps(chamber,World.TicksPerHour*5);Require(q.Escaped&&q.Escape==100&&chamber.Region.History.Any(h=>h.Kind=="ContainmentFailure"),"Unmet containment did not accumulate an explained failure.");Console.WriteLine("PASS H04 failure: living downed capture, suppression, visible unmet environment requirements, progressive warnings and state-driven escape");
  // A stable grounded specimen uses the actual engineering network; study requires a physically attending keeper.
  var safe=InstitutionsWorldGenerator.Create(d,74219);long sk=safe.Colony.People.Keys.First();var sg=safe.Apply(new(CommandKind.Spawn,DefinitionId:"vault-guardian",X:53,Y:65),d);Require(sg.Accepted,sg.Message);safe.Body(sg.EntityId)!.Downed=true;Cmd(safe,new(CommandKind.Teleport,sk,X:54,Y:65));safe.Colony.People[sk].Drafted=true;Cmd(safe,new(CommandKind.InstitutionAction,sk,TargetId:sg.EntityId,Text:"contain"));safe.Colony.People[sk].Drafted=false;safe.Colony.People[sk].Priorities=new int[16];safe.Colony.People[sk].Schedule=Enumerable.Repeat(ScheduleActivity.Work,24).ToArray();var sq=safe.Society.Containments.Single();safe.Apply(new(CommandKind.Spawn,DefinitionId:"column",X:54,Y:66),d);safe.Slice.Roofs.Add(sq.Cell);sq.Feed=6;safe.RefreshEngineering(d);Require(safe.ContainmentRequirements(sq).All(r=>r.Value),"Seed engineering ward does not satisfy safe containment: "+string.Join(',',safe.ContainmentRequirements(sq)));
  // Keep the resident beside the ward through ordinary hold orders, then allow study while undrafted between hours.
  sq.StudyRate=1;for(int hour=0;hour<8;hour++){safe.Interrupt(sk,d);safe.Find(sk)!.X=54;safe.Find(sk)!.Y=65;safe.Colony.People[sk].Food=1000;safe.Colony.People[sk].Rest=1000;Steps(safe,World.TicksPerHour);}Require(sq.Knowledge==8&&safe.Slice.Formulae[sk].Known.Contains("door"),"Attended safe study gave no countermeasure.");sq.StudyRate=0;int low=sq.Stability;Steps(safe,World.TicksPerHour);Require(sq.Stability>low,"Resting containment did not recover stability.");Save("containment-studied",safe);Console.WriteLine("PASS H04 safe study: actual roof, surface light/climate, powered ward, ration depletion, attended knowledge, countermeasure and stability recovery");
  // Preserve an identifiable crafted building, a unique artifact, old wounds, family and institutions.
  w.Interrupt(teacher,d);w.Interrupt(student,d);w.Find(host.Id)!.Name="The Founders' Library";w.Find(host.Id)!.CraftQuality=87;w.InflictWound(student,"left-leg","Bruise",2,0,d);var ancient=w.Region.Artifacts.Single(a=>a.Custody=="Colony");long ancientId=ancient.Id;int age=w.Colony.People[student].Age;int condition=w.Find(host.Id)!.Health;w.Region.Factions[0].Grievance=42;Save("retirement-ready",w,"History");var next=w.BeginSuccessor(d,5);Require(next.Region.Sites.Count==14&&next.Region.Artifacts.Single(a=>a.Id==ancientId).Custody=="Site"&&next.Region.Factions[0].Grievance==42,"Retirement lost world claims/identity.");Save("successor-settlement",next,"History");next=SaveStore.Read(Path.Combine(output,"successor-settlement.lastlight"),d).World;
  var reclaimed=next.ReclaimLegacy(d);Require(reclaimed.Find(host.Id)!.Name=="The Founders' Library"&&reclaimed.Find(host.Id)!.Health==condition*85/100&&reclaimed.Colony.People[student].Age==age+5&&reclaimed.Body(student)!.Wounds.Count>0&&reclaimed.Society.Families.Count==1&&reclaimed.Society.Apprentices.Single().Graduated&&reclaimed.Region.Artifacts.Single(a=>a.Id==ancientId).LocalEntityId==ancient.LocalEntityId,"Reclaim did not convert the actual prior settlement.");Save("reclaimed-settlement",reclaimed,"History");Require(!reclaimed.CanRetire().Accepted,"Second retirement bypassed campaign bound.");Console.WriteLine("PASS H05 reclaim: documented elapsed years, exact condition/stock decay, existing wounds, aging, family, graduated apprentice and unique artifact identity persist; no second retirement");
  long leader=next.Colony.People.Keys.First();var retired=next.Region.Sites.Single(s=>s.Id==next.Society.Legacy!.SiteId);var provisions=next.Apply(new(CommandKind.Spawn,DefinitionId:"meal",X:62,Y:67,Quantity:8),d);Require(provisions.Accepted,provisions.Message);Cmd(next,new(CommandKind.RegionAction,leader,leader.ToString(),TargetId:retired.Id,Quantity:2,Text:"depart"));var party=next.Region.Parties.Last();Until(next,()=>party.State=="AtSite",25000,"Successor expedition to retired settlement");var map=next.Society.Legacy!.EntityMap;Require(next.Levels==7&&map.ContainsKey(host.Id)&&next.Find(map[host.Id])!.Name=="The Founders' Library"&&next.Find(map[host.Id])!.CraftQuality==87&&next.Find(map[host.Id])!.Health==condition*85/100&&next.Colony.People[map[student]].Age==age+5&&next.Body(map[student])!.Wounds.Count>0&&next.Region.Artifacts.Single(a=>a.Id==ancientId).LocalEntityId==map[ancient.LocalEntityId]&&next.Region.History.Any(h=>h.Kind=="LegacyEncounter"),"EXIT H: successor did not encounter actual prior consequences.");Save("successor-legacy-encounter",next,"World");var encounter=SaveStore.Read(Path.Combine(output,"successor-legacy-encounter.lastlight"),d).World;Require(SaveStore.Fingerprint(next)==SaveStore.Fingerprint(encounter),"Legacy encounter roundtrip differs.");Steps(next,300);Steps(encounter,300);Require(SaveStore.Fingerprint(next)==SaveStore.Fingerprint(encounter),"Legacy encounter continuation differs.");Console.WriteLine("PASS H EXIT GATE: after save/reload a real provisioned successor expedition encounters copied prior terrain/structures, aging and injuries, persistent faction grievance and the same unique artifact on seven elevations");
  string fixture=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(assets))!,"../../../tests/fixtures/living-world.lastlight");var envelope=JsonSerializer.Deserialize<SaveEnvelope>(File.ReadAllText(fixture),JsonFormat.Options)!;Require(envelope.FormatVersion==7,"G migration fixture changed.");var migrated=SaveStore.Read(fixture,d).World;Require(!migrated.Society.Enabled&&migrated.Region.Enabled&&migrated.Region.Sites.Count==13,"G migration changed the living world.");Cmd(migrated,new(CommandKind.InstitutionAction,Text:"enable"));Require(migrated.Society.Enabled&&migrated.Region.Sites.Count==13,"Opt-in altered prior region.");migrated.Validate(d);Console.WriteLine("PASS H migration: authentic format-7 region retains the map, artifacts, factions and RNG with institutions disabled");
  var invalid=InstitutionsWorldGenerator.Create(d,74219);invalid.Society.Containments.Add(new(){EntityId=999999,KeeperId=teacher});bool rejected=false;try{invalid.Validate(d);}catch(InvalidDataException){rejected=true;}Require(rejected,"Malformed containment accepted.");Console.WriteLine("PASS H integrity: malformed identities, membership, containment and embedded archives rejected");
 }
}
